@push('scripts')
<script>
const wsToken = document.querySelector('meta[name="csrf-token"]').content;
const setUrl = @json(route('workouts.sessions.sets.store', $workoutSession));
const toast = message => { const el = document.getElementById('toast'); el.textContent = message; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 1800); };
const payloadFor = (row, card) => { const data = { workout_exercise_id: card.dataset.exerciseId, set_number: row.dataset.setNumber, exercise_note: card.querySelector('[data-exercise-note]').value, completed: true }; row.querySelectorAll('[data-field]').forEach(input => { if (input.value !== '') data[input.dataset.field] = input.value; }); return data; };
async function saveRow(row, card) { const button = row.querySelector('.ws-save-set'); button.disabled = true; try { const response = await fetch(setUrl, { method:'POST', headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':wsToken}, body:JSON.stringify(payloadFor(row, card)) }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Could not save set'); row.classList.add('is-saved'); button.classList.add('saved'); button.textContent = 'Saved'; const status = card.querySelector('[data-exercise-status]'); status.textContent = data.exercise_completed ? 'Completed' : 'In progress'; status.classList.toggle('green', data.exercise_completed); status.classList.toggle('gray', !data.exercise_completed); updateProgress(); toast('Set saved'); } catch (error) { toast(error.message); } finally { button.disabled = false; } }
function updateProgress() { const cards = [...document.querySelectorAll('[data-exercise-card]')]; const completed = cards.filter(card => card.querySelector('[data-exercise-status]')?.classList.contains('green')).length; document.getElementById('doneCount').textContent = completed; document.getElementById('progressFill').style.width = (cards.length ? completed / cards.length * 100 : 0) + '%'; }
 document.querySelectorAll('[data-exercise-card]').forEach(card => { card.querySelectorAll('.ws-save-set').forEach(button => button.addEventListener('click', () => saveRow(button.closest('[data-set-row]'), card))); card.querySelectorAll('[data-field]').forEach(input => input.addEventListener('keydown', event => { if (event.key === 'Enter') { event.preventDefault(); saveRow(input.closest('[data-set-row]'), card); } })); card.querySelector('.ws-add-set').addEventListener('click', () => { const list = card.querySelector('.set-list'); const number = list.children.length + 1; const row = document.createElement('div'); row.className = 'ws-set-row'; row.dataset.setNumber = number; row.innerHTML = `<span class="ws-set-no">${number}</span><input class="ws-input" data-field="reps" type="number" min="0" step="0.5" placeholder="reps"><input class="ws-input" data-field="weight" type="number" min="0" step="0.01" placeholder="kg"><input class="ws-input" data-field="duration_seconds" type="number" min="0" placeholder="sec"><input class="ws-input" data-field="rir" type="number" min="0" max="10" step="0.5" placeholder="RIR"><select class="ws-input" data-field="form_rating"><option value="">—</option><option value="1">1/5</option><option value="2">2/5</option><option value="3">3/5</option><option value="4">4/5</option><option value="5">5/5</option></select><input class="ws-input" data-field="pain_level" type="number" min="0" max="10" placeholder="0"><input class="ws-input" data-field="note" placeholder="Optional"><button type="button" class="ws-save-set">Save</button>`; row.querySelector('button').addEventListener('click', () => saveRow(row, card)); list.appendChild(row); row.querySelector('[data-field="reps"]').focus(); }); card.querySelector('.skip-exercise').addEventListener('click', async () => { const reason = prompt('Why are you skipping this movement?'); if (!reason) return; const response = await fetch(setUrl, { method:'POST', headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':wsToken}, body:JSON.stringify({workout_exercise_id:card.dataset.exerciseId,set_number:1,completed:false,skip_reason:reason,exercise_note:card.querySelector('[data-exercise-note]').value}) }); if (response.ok) { card.querySelector('[data-exercise-status]').textContent = 'Skipped'; card.querySelector('[data-exercise-status]').classList.remove('gray','green'); card.querySelector('[data-exercise-status]').classList.add('gray'); toast('Movement skipped'); } }); });
let timer; document.querySelectorAll('.start-rest').forEach(button => button.addEventListener('click', () => { clearInterval(timer); let remaining = Number(button.dataset.seconds); const label = document.getElementById('restTimer'); const stop = document.getElementById('stopTimer'); stop.style.display = ''; const render = () => { label.textContent = `${Math.floor(remaining / 60)}:${String(remaining % 60).padStart(2,'0')}`; }; render(); timer = setInterval(() => { remaining--; render(); if (remaining <= 0) { clearInterval(timer); label.textContent = 'Rest complete'; } }, 1000); stop.onclick = () => { clearInterval(timer); label.textContent = ''; stop.style.display = 'none'; }; }));
document.querySelectorAll('.use-previous').forEach(button => button.addEventListener('click', () => { const card = button.closest('[data-exercise-card]'); JSON.parse(button.dataset.previous).forEach(previous => { const row = card.querySelector(`[data-set-number="${previous.set_number}"]`); if (!row) return; ['reps', 'weight', 'rir'].forEach(field => { const input = row.querySelector(`[data-field="${field}"]`); if (input && !input.value && previous[field] !== null) input.value = previous[field]; }); }); toast('Previous values copied'); }));
const timerLabel = document.getElementById('sessionTimer'); const started = Number(timerLabel.dataset.started); setInterval(() => { const minutes = Math.max(0, Math.floor((Date.now() / 1000 - started) / 60)); if ({{ $workoutSession->status === 'in_progress' ? 'true' : 'false' }}) timerLabel.textContent = minutes + ' min'; }, 30000);
</script>
@endpush
